    fun extraSaqs(subject: WbbseSubject): List<SaqQuestion> = when (subject) {
        WbbseSubject.LIFE_SCIENCE -> listOf(
            SaqQuestion("lsc_saq_4", subject, "অ্যানাফেজ দশার দুটি প্রধান বৈশিষ্ট্য লেখো।", 2, "১. সেন্ট্রোমিয়ার বিভাজিত হয়ে দুটি অপত্য ক্রোমোজোম সৃষ্টি হয়।\n২. বেমতন্তুর সংকোচনে অপত্য ক্রোমোজোমগুলি V, L, J বা I আকারে বিপরীত মেরুর দিকে চলন (অ্যানাফেজীয় চলন) করে।", listOf("সেন্ট্রোমিয়ার", "অপত্য", "মেরু", "v, l, j", "বেমতন্তু")),
            SaqQuestion("lsc_saq_5", subject, "ইনসুলিন ও গ্লুকাগন হরমোনকে পরস্পরের বিপরীতধর্মী বলা হয় কেন?", 2, "অগ্ন্যাশয়ের β-কোষ থেকে ক্ষরিত ইনসুলিন রক্তে শর্করার মাত্রা কমায়, আর α-কোষ থেকে ক্ষরিত গ্লুকাগন রক্তে শর্করার মাত্রা বাড়ায়।", listOf("ইনসুলিন", "গ্লুকাগন", "শর্করা", "অগ্ন্যাশয়", "বিপরীত")),
            SaqQuestion("lsc_saq_6", subject, "জিনোটাইপ ও ফিনোটাইপের মধ্যে পার্থক্য লেখো।", 2, "কোনো জীবের বাহ্যিক প্রকাশিত বৈশিষ্ট্যকে ফিনোটাইপ (যেমন লম্বা/বেঁটে) এবং ওই বৈশিষ্ট্যের জন্য দায়ী জিনগত গঠনকে জিনোটাইপ (যেমন TT, Tt, tt) বলে।", listOf("বাহ্যিক", "জিনগত", "tt", "ফিনোটাইপ", "জিনোটাইপ")),
            SaqQuestion("lsc_saq_7", subject, "হিমোফিলিয়াকে ‘রয়্যাল ডিজিজ’ বা X-ক্রোমোজোম বাহিত রোগ বলা হয় কেন?", 2, "হিমোফিলিয়ার প্রচ্ছন্ন জিনটি X-ক্রোমোজোমে অবস্থিত থাকায় এটি X-লিঙ্কড বংশগত রোগ, যাতে রক্ততঞ্চন ফ্যাক্টর VIII/IX-এর অভাবে রক্তক্ষরণ বন্ধ হয় না।", listOf("x-ক্রোমোজোম", "রক্ততঞ্চন", "প্রচ্ছন্ন", "ফ্যাক্টর")),
            SaqQuestion("lsc_saq_8", subject, "সমসংস্থ ও সমবৃত্তীয় অঙ্গের একটি করে উদাহরণসহ পার্থক্য লেখো।", 2, "সমসংস্থ অঙ্গ উৎপত্তিতে এক কিন্তু কাজে ভিন্ন (মানুষের হাত ও পাখির ডানা — অপসারী বিবর্তন)। সমবৃত্তীয় অঙ্গ উৎপত্তিতে ভিন্ন কিন্তু কাজে এক (পাখির ডানা ও পতঙ্গের ডানা — অভিসারী বিবর্তন)।", listOf("উৎপত্তি", "কাজ", "অপসারী", "অভিসারী", "ডানা")),
            SaqQuestion("lsc_saq_9", subject, "জীববৈচিত্র্য হটস্পট (Hotspot) কাকে বলে? ভারতের দুটি হটস্পটের নাম লেখো।", 2, "যে নির্দিষ্ট অঞ্চলে প্রচুর এন্ডেমিক প্রজাতি বাস করে কিন্তু মানুষের চাপে তারা বিপন্ন, তাকে হটস্পট বলে। ভারতের দুটি হটস্পট: পূর্ব হিমালয় ও পশ্চিমঘাট।", listOf("এন্ডেমিক", "বিপন্ন", "পূর্ব হিমালয়", "পশ্চিমঘাট")),
            SaqQuestion("lsc_saq_10", subject, "সুন্দরী গাছের শ্বাসমূলের (Pneumatophore) দুটি অভিযোজনগত গুরুত্ব লেখো।", 2, "১. লবণাক্ত কাদামাটিতে অক্সিজেনের অভাব মেটাতে মূল অভিকর্ষের বিপরীতে খাড়া হয়ে শ্বাসছিদ্র দিয়ে O₂ গ্রহণ করে।\n২. গাছটিকে কাদামাটিতে শ্বসন চালাতে সাহায্য করে।", listOf("শ্বাসছিদ্র", "অক্সিজেন", "লবণাক্ত", "কাদামাটি", "শ্বসন"))
        )

        WbbseSubject.HISTORY -> listOf(
            SaqQuestion("his_saq_4", subject, "১৮৫৭ সালের মহাবিদ্রোহের প্রত্যক্ষ কারণ কী ছিল?", 2, "ব্রিটিশ সেনাবাহিনীতে নতুন এনফিল্ড রাইফেলের টোটায় গরু ও শূকরের চর্বি মেশানো আছে—এই সংবাদ ছড়িয়ে পড়ায় হিন্দু ও মুসলিম সিপাহীদের ধর্মীয় অনুভূতিতে আঘাত লাগে এবং বিদ্রোহ শুরু হয়।", listOf("এনফিল্ড", "চর্বি", "সিপাহী", "মঙ্গল পাণ্ডে", "১৮৫৭")),
            SaqQuestion("his_saq_5", subject, "‘মেকলে মিনিট’ (১৮৩৫) কী? এর মূল লক্ষ্য কী ছিল?", 2, "১৮৩৫ সালে লর্ড মেকলে ভারতে পাশ্চাত্য ও ইংরেজি শিক্ষার প্রবর্তনের পক্ষে যে প্রস্তাব পেশ করেন তা মেকলে মিনিট নামে পরিচিত। এর লক্ষ্য ছিল ইংরেজি-শিক্ষিত ভারতীয় কেরানি শ্রেণি তৈরি করা।", listOf("১৮৩৫", "ইংরেজি", "পাশ্চাত্য", "কেরানি", "মেকলে")),
            SaqQuestion("his_saq_6", subject, "বাংলার ছাপাখানা বিস্তারে উপেন্দ্রকিশোর রায়চৌধুরীর (ইউ. রায় অ্যান্ড সন্স) দুটি অবদান লেখো।", 2, "১. তিনি বাংলায় আধুনিক হাফটোন (Halftone) ব্লক প্রিন্টিং ও রঙিন ছবি ছাপার প্রযুক্তি চালু করেন।\n২. ১৯১৩ সালে জনপ্রিয় ছোটোদের পত্রিকা ‘সন্দেশ’ প্রকাশ করেন।", listOf("হাফটোন", "ইউ. রায়", "সন্দেশ", "রঙিন")),
            SaqQuestion("his_saq_7", subject, "তিনকাঠিয়া প্রথা কী ছিল?", 2, "বিহারের চম্পারণ জেলায় নীলকর সাহেবরা কৃষকদের জমির প্রতি বিঘার ৩/২০ অংশে (তিন কাঠায়) বাধ্যতামূলকভাবে নীল চাষ করতে বাধ্য করত। ১৯১৭ সালে গান্ধীজি এর বিরুদ্ধে সত্যাগ্রহ করেন।", listOf("চম্পারণ", "৩/২০", "নীল", "গান্ধীজি", "১৯১৭")),
            SaqQuestion("his_saq_8", subject, "‘অলিন্দ যুদ্ধ’ (৮ ডিসেম্বর ১৯৩০) কী?", 2, "বেঙ্গল ভলান্টিয়ার্সের তিন বিপ্লবী বিনয় বসু, বাদল গুপ্ত ও দীনেশ গুপ্ত কলকাতার রাইটার্স বিল্ডিং-এ প্রবেশ করে অত্যাচারী কারা-প্রধান সিম্পসনকে হত্যা করে যে সশস্ত্র লড়াই করেন, তা অলিন্দ যুদ্ধ নামে খ্যাত।", listOf("বিনয়", "বাদল", "দীনেশ", "রাইটার্স", "সিম্পসন")),
            SaqQuestion("his_saq_9", subject, "‘ইন্সট্রুমেন্ট অব অ্যাকসেশন’ (Instrument of Accession) কী?", 2, "১৯৪৭ সালে স্বাধীনতার পর দেশীয় রাজ্যগুলির ভারত বা পাকিস্তানে যোগদানের জন্য যে আইনি চুক্তিপত্রে রাজারা স্বাক্ষর করেছিলেন, তাকে ভারতভুক্তির দলিল বা Instrument of Accession বলে।", listOf("দেশীয় রাজ্য", "চুক্তিপত্র", "১৯৪৭", "ভারতভুক্তি")),
            SaqQuestion("his_saq_10", subject, "‘কার্লাইল সার্কুলার’ (১৯০৫) কেন জারি করা হয়েছিল?", 2, "বঙ্গভঙ্গ-বিরোধী স্বদেশী আন্দোলনে বাংলার ছাত্রসমাজের অংশগ্রহণ বন্ধ করতে এবং আন্দোলনকারী ছাত্রদের স্কুল-কলেজ থেকে বহিষ্কারের হুমকি দিতে ১৯০৫ সালে চিফ সেক্রেটারি আর.ডব্লিউ. কার্লাইল এই নির্দেশনামা জারি করেন।", listOf("১৯০৫", "বঙ্গভঙ্গ", "স্বদেশী", "ছাত্র", "বহিষ্কার"))
        )

        WbbseSubject.GEOGRAPHY -> listOf(
            SaqQuestion("geo_saq_4", subject, "বার্খান ও সিফ বালিয়াড়ির মধ্যে দুটি পার্থক্য লেখো।", 2, "১. বার্খান বায়ুপ্রবাহের সাথে আড়াআড়িভাবে গড়ে ওঠা অর্ধচন্দ্রাকৃতি বালিয়াড়ি; সিফ বায়ুপ্রবাহের সমান্তরালে গড়ে ওঠা দীর্ঘ তলোয়ারের মতো বালিয়াড়ি।\n২. বার্খানের দুটি শিং থাকে, সিফের ধারালো শীর্ষদেশ থাকে।", listOf("অর্ধচন্দ্রাকৃতি", "তলোয়ার", "আড়াআড়ি", "সমান্তরাল")),
            SaqQuestion("geo_saq_5", subject, "ওজোন স্তর ধ্বংসের দুটি প্রধান কারণ ও একটি ফলাফল লেখো।", 2, "কারণ: CFC (ক্লোরোফ্লুরোকার্বন) ও নাইট্রোজেন অক্সাইড নিঃসরণ। ফলাফল: ক্ষতিকর UV রশ্মি পৃথিবীতে এসে ত্বকের ক্যান্সার ও ছানি রোগ বাড়ায়।", listOf("cfc", "uv", "ক্যান্সার", "স্ট্র্যাটোস্ফিয়ার")),
            SaqQuestion("geo_saq_6", subject, "পশ্চিমী ঝঞ্ঝা (Western Disturbance) কাকে বলে?", 2, "শীতকালে ভূমধ্যসাগরীয় অঞ্চল থেকে আগত দুর্বল নাতিশীতোষ্ণ ঘূর্ণবাতের প্রভাবে উত্তর-পশ্চিম ভারতে হালকা বৃষ্টিপাত ও হিমালয়ে তুষারপাত ঘটে—একে পশ্চিমী ঝঞ্ঝা বলে। এটি রবি শস্য (গম) চাষের জন্য উপকারী।", listOf("শীতকাল", "ভূমধ্যসাগর", "উত্তর-পশ্চিম", "গম")),
            SaqQuestion("geo_saq_7", subject, "সামাজিক বনসৃজন (Social Forestry)-এর দুটি উদ্দেশ্য লেখো।", 2, "১. রাস্তার ধার, পতিত জমি ও রেললাইনের পাশে বৃক্ষরোপণ করে অরণ্যের পরিমাণ বৃদ্ধি ও পরিবেশ সুরক্ষা।\n২. গ্রামীণ মানুষের জ্বালানি কাঠ ও পশুখাদ্যের চাহিদা মেটানো।", listOf("পতিত জমি", "বৃক্ষরোপণ", "জ্বালানি", "পরিবেশ")),
            SaqQuestion("geo_saq_8", subject, "ভারতে জনসংখ্যা বণ্টনের তারতম্যের দুটি প্রাকৃতিক কারণ লেখো।", 2, "১. ভূপ্রকৃতি: উর্বর সমভূমিতে (গাঙ্গেয় সমভূমি) ঘনবসতি, কিন্তু পার্বত্য ও মরু অঞ্চলে বিরল বসতি।\n২. জলবায়ু ও জলসম্পদ: অনুকূল মৌসুমি জলবায়ু ও নদী তীরে জনঘনত্ব বেশি।", listOf("সমভূমি", "ভূপ্রকৃতি", "জলবায়ু", "গাঙ্গেয়")),
            SaqQuestion("geo_saq_9", subject, "মৌসুমি বিস্ফোরণ (Burst of Monsoon) কী?", 2, "জুন মাসের প্রথম সপ্তাহে দক্ষিণ-পশ্চিম মৌসুমি বায়ু আরব সাগর থেকে প্রচুর জলীয় বাষ্প নিয়ে কেরলের মালাবার উপকূলে হঠাৎ প্রবল বজ্রবিদ্যুৎসহ ভারী বর্ষণ ঘটায়—একে মৌসুমি বিস্ফোরণ বলে।", listOf("জুন", "কেরল", "মালাবার", "দক্ষিণ-পশ্চিম", "ভারী বর্ষণ")),
            SaqQuestion("geo_saq_10", subject, "উপগ্রহ চিত্র (Satellite Imagery)-এর দুটি প্রধান ব্যবহার লেখো।", 2, "১. আবহাওয়ার পূর্বাভাস ও ঘূর্ণিঝড়ের গতিপথ নির্ণয়।\n২. অরণ্যের বিস্তৃতি, ফসলের উৎপাদন ও প্রাকৃতিক দুর্যোগের ক্ষয়ক্ষতি পরিমাপ।", listOf("আবহাওয়া", "ঘূর্ণিঝড়", "অরণ্য", "দুর্যোগ"))
        )

        else -> emptyList()
    }

    fun extraLongs(subject: WbbseSubject): List<LongQuestion> = when (subject) {
